-- -----------------------------------------------------
-- procedure genera_scontrino
-- -----------------------------------------------------

USE `Pizzeria`;
DROP procedure IF EXISTS `Pizzeria`.`genera_scontrino`;

DELIMITER $$
USE `Pizzeria`$$
CREATE PROCEDURE `genera_scontrino` (
    IN p_data_comanda DATE,
    IN p_numero_comanda SMALLINT UNSIGNED
)
BEGIN

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		ROLLBACK;
		RESIGNAL;
	END;
    
	SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
	SET TRANSACTION READ ONLY;
	START TRANSACTION;

    SELECT ip.nome_prodotto, COUNT(*) AS quantita, ip.prezzo_applicato AS prezzo_unitario, SUM(ip.prezzo_applicato) AS subtotale
    FROM IstanzaProdotto AS ip
    JOIN Comanda AS c ON c.data = ip.data_comanda AND c.numero = ip.numero_comanda
    WHERE ip.data_comanda = p_data_comanda AND ip.numero_comanda = p_numero_comanda AND c.stato = 'completata'
    GROUP BY ip.nome_prodotto, ip.prezzo_applicato
    ORDER BY ip.nome_prodotto;

    SELECT conto AS totale
    FROM Comanda
    WHERE data = p_data_comanda AND numero = p_numero_comanda AND stato = 'completata';
    
    COMMIT;
END$$

