    FROM EntrataMensile
    WHERE anno = CAST(LEFT(p_anno_mese, 4) AS UNSIGNED) AND mese = CAST(RIGHT(p_anno_mese, 2) AS UNSIGNED);
    
    COMMIT;
END$$

