-- -----------------------------------------------------
-- procedure crea_user
-- -----------------------------------------------------

USE `Pizzeria`;
DROP procedure IF EXISTS `Pizzeria`.`crea_user`;

DELIMITER $$
USE `Pizzeria`$$
CREATE PROCEDURE `crea_user` (
    IN p_username VARCHAR(45),
    IN p_password VARCHAR(100),
    IN p_ruolo VARCHAR(20)
)
BEGIN
    IF TRIM(p_username) = '' OR p_password = '' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Username e password non possono essere vuoti';
    END IF;

    INSERT INTO `User` (username, password, ruolo)
    VALUES (p_username, MD5(p_password), p_ruolo);
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure login
-- -----------------------------------------------------

USE `Pizzeria`;
DROP procedure IF EXISTS `Pizzeria`.`login`;

DELIMITER $$
USE `Pizzeria`$$
CREATE PROCEDURE `login` (
    IN p_username VARCHAR(45),
    IN p_password VARCHAR(100),
    OUT p_ruolo INT
)
BEGIN
    DECLARE v_ruolo ENUM(
        'manager',
        'cameriere',
        'pizzaiolo',
        'barman'
    );

    SELECT ruolo
    INTO v_ruolo
    FROM `User`
    WHERE username = p_username AND password = MD5(p_password);

    IF v_ruolo = 'manager' THEN
        SET p_ruolo = 1;
    ELSEIF v_ruolo = 'cameriere' THEN
        SET p_ruolo = 2;
    ELSEIF v_ruolo = 'pizzaiolo' THEN
        SET p_ruolo = 3;
    ELSEIF v_ruolo = 'barman' THEN
        SET p_ruolo = 4;
    ELSE
        SET p_ruolo = 5;
    END IF;
END$$

DELIMITER ;

