        WHERE data = NEW.data
    ) AND NEW.numero <> 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La prima comanda della giornata deve avere numero zero';
    END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_comanda_bu_conto` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_comanda_bu_conto` BEFORE UPDATE ON `Comanda` FOR EACH ROW
BEGIN
	DECLARE v_conto DECIMAL(8,2);

	IF OLD.stato = 'aperta' AND NEW.stato = 'completata' THEN
		IF NOT EXISTS (
			SELECT 1
			FROM IstanzaProdotto
			WHERE data_comanda = OLD.data AND numero_comanda = OLD.numero
		) THEN
			SIGNAL SQLSTATE '45000'
			SET MESSAGE_TEXT = 'Non è possibile completare una comanda senza prodotti';
		END IF;
	 
		IF EXISTS (
			SELECT 1
			FROM IstanzaProdotto
			WHERE data_comanda = OLD.data 
				AND numero_comanda = OLD.numero
				AND stato = 'non pronta'
		) THEN
			SIGNAL SQLSTATE '45000'
			SET MESSAGE_TEXT = 'La comanda contiene prodotti non ancora pronti';
		END IF;

		SELECT SUM(prezzo_applicato)
		INTO v_conto
		FROM IstanzaProdotto
		WHERE data_comanda = OLD.data AND numero_comanda = OLD.numero;
		
		SET NEW.conto = v_conto;
	END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_istanza_bi_prezzo` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_istanza_bi_prezzo` BEFORE INSERT ON `IstanzaProdotto` FOR EACH ROW
BEGIN
    SET NEW.prezzo_applicato = (
        SELECT prezzo
        FROM Prodotto
        WHERE nome = NEW.nome_prodotto
    );
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_asporto_bi_tavolo` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_asporto_bi_tavolo` BEFORE INSERT ON `OrdineDaAsporto` FOR EACH ROW
BEGIN
    IF EXISTS (
        SELECT 1
        FROM Occupare
        WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    )
    OR EXISTS (
		SELECT 1
        FROM OrdineInConsegna
        WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La comanda è già associata a un tavolo o a un ordine in consegna';
    END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_consegna_bi_tavolo` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_consegna_bi_tavolo` BEFORE INSERT ON `OrdineInConsegna` FOR EACH ROW
BEGIN
    IF EXISTS (
        SELECT 1
        FROM Occupare
        WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    )
    OR EXISTS (
		SELECT 1
        FROM OrdineDaAsporto
		WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La comanda è già associata a un tavolo o a un ordine da asporto';
    END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_occupare_bi_ordine` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_occupare_bi_ordine` BEFORE INSERT ON `Occupare` FOR EACH ROW
BEGIN
    IF EXISTS (
        SELECT 1
        FROM OrdineDaAsporto
        WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    ) OR EXISTS (
        SELECT 1
        FROM OrdineInConsegna
        WHERE data_comanda = NEW.data_comanda AND numero_comanda = NEW.numero_comanda
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La comanda è già associata a un ordine da asporto o a un ordine in consegna';
    END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_occupare_ai_tavolo` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_occupare_ai_tavolo` AFTER INSERT ON `Occupare` FOR EACH ROW
BEGIN
    UPDATE Tavolo
    SET stato = 'occupato'
    WHERE numero = NEW.numero_tavolo;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_occupare_bd_comanda` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_occupare_bd_comanda` BEFORE DELETE ON `Occupare` FOR EACH ROW
BEGIN
    IF (
        SELECT stato
        FROM Comanda
        WHERE data = OLD.data_comanda AND numero = OLD.numero_comanda
    ) <> 'completata' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Il tavolo può essere liberato solo dopo il completamento della comanda';
    END IF;
END$$


USE `Pizzeria`$$
DROP TRIGGER IF EXISTS `Pizzeria`.`trg_occupare_ad_tavolo` $$
USE `Pizzeria`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Pizzeria`.`trg_occupare_ad_tavolo` AFTER DELETE ON `Occupare` FOR EACH ROW
BEGIN
    UPDATE Tavolo
    SET stato = 'libero'
    WHERE numero = OLD.numero_tavolo;
END$$


